// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        // The admin of the contract is msg.sender from deployment (the test contract)
        // We need to find admin – but admin is private, so we cannot read it.
        // Instead we assume the caller is the admin – the test contract itself
        vm.prank(address(this));
        bool success = c.setOwner(newOwner);
        assertTrue(success);
    }
}

